include <robotics.scad>
// Intel RealSense D457 housing. Origin: base centre (x=0 = 1/4-20 centreline, y=0 mid-depth, z=0 bottom).
L = 124; D = 36; H = 29;          // envelope, mm (datasheet)
zc = 14.5;                         // optical / connector height (drawing (14.50))
// front window (NOT dimensioned: plain conservative inset)
win = [114, 22]; win_d = 1.5;
// rear M4 inserts: 61.5 apart (dimensioned); x positions scaled from drawing
m4_x = [23.75, -37.75]; m4_depth = 6; m4_d = 4.0;
// bottom 1/4-20: x=0 dimensioned; y scaled from section A-A
q_y = -2.7; q_d = 6.35; q_depth = 9;
// FAKRA boss pocket: axis along X, 9.5 from rear face, from x=43 (ref) out to the +X end
fk_y = D/2 - 9.5; fk_sq = 9.6; fk_x0 = 43;
$fn = 48;
module body()
  translate([0, D/2, zc]) xrot(90)
    offset_sweep(rect([L, H], rounding = H/2 - 0.01), height = D,
                 bottom = os_circle(r = 1.0), top = os_circle(r = 3));
difference() {
  body();
  // front window recess
  translate([0, -D/2 - 0.01, zc]) xrot(-90)
    linear_extrude(win_d + 0.01) rect(win, rounding = win.y/2 - 0.01);
  // rear M4 threaded inserts
  for (x = m4_x) translate([x, D/2 + 0.01, zc]) ycyl(d = m4_d, h = m4_depth, anchor = BACK);
  // bottom 1/4-20 insert
  translate([0, q_y, -0.01]) cyl(d = q_d, h = q_depth, anchor = BOT);
  // FAKRA tunnel, open at the +X end
  translate([fk_x0, fk_y, zc]) cuboid([L/2 - fk_x0 + 1, fk_sq, fk_sq], anchor = LEFT);
}

include <robotics.scad>
// Front window, flush with the front face (y=-18). Origin: base centre of camera.
win = [114, 22]; t = 1.5; zc = 14.5; D = 36;
opt_x = [-47.5, -11.5, 10, 47.5]; ap = 8;   // aperture Ø NOT dimensioned
$fn = 48;
difference() {
  translate([0, -D/2, zc]) xrot(-90) linear_extrude(t) rect(win, rounding = win.y/2 - 0.01);
  for (x = opt_x) translate([x, -D/2 + t/2, zc]) ycyl(d = ap, h = t + 1);
}

include <robotics.scad>
// Lens discs filling the window apertures (flush with front face y=-18).
opt_x = [-47.5, -11.5, 10, 47.5]; ap = 8; t = 1.5; zc = 14.5; D = 36;
$fn = 48;
for (x = opt_x) translate([x, -D/2 + t/2, zc]) ycyl(d = ap - 0.2, h = t);

include <robotics.scad>
// FAKRA jack in the +X end tunnel. Origin: camera base centre.
x0 = 43; x1 = 57.6; sq = 9.2; y = 36/2 - 9.5; zc = 14.5;
$fn = 40;
difference() {
  translate([x0, y, zc]) cuboid([x1 - x0, sq, sq], chamfer = 0.4, edges = "X", anchor = LEFT);
  translate([x1 + 0.01, y, zc]) xcyl(d = 6.0, h = 8, anchor = RIGHT);   // mating cavity
}
translate([x1 - 8, y, zc]) xcyl(d = 1.2, h = 7.5, anchor = LEFT);       // centre pin
